import (
	"encoding/json"
	"fmt"
	"os"

	"github.com/avrapitov/go-avro"
)

// Define the Go struct
type MyStruct struct {
	Name string `json:"name"`
}

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run script.go <GoSourceFile> <structName>")
		os.Exit(1)
	}

	goFileName := os.Args[1]
	structName := os.Args[2]

	// Parse the Go code
	var myStruct MyStruct
	err := json.Unmarshal([]byte(goFileName), &myStruct)
	if err != nil {
		fmt.Printf("Error parsing %s: %v\n", goFileName, err)
		return
	}

