	schema, err := avro.NewSchemaFromStruct(&myStruct)
	if err != nil {
		fmt.Printf("Error generating schema: %v\n", err)
		return
	}
	defer schema.Close()

	// Write the schema to a file
	file, err := os.Create(fmt.Sprintf("%s.avsc", structName))
	if err != nil {
		fmt.Printf("Error creating file: %v\n", err)
		return
	}
	defer file.Close()

	_, err = io.Copy(file, schema)
	if err != nil {
		fmt.Printf("Error writing to file: %v\n", err)
		return
	}

	fmt.Printf("Avro schema generated successfully as %s.avsc\n", structName)
}
```

